    public void guide(){Kit.Sheet s=k.new Sheet(t("First flight","اولین فرمان"));s.note(t("01   Start locally\nTry “device report then list apps”. These steps use no cloud requests.\n\n02   Add intelligence\nConnect a personal Gemini key for free-form and conditional tasks. Commands and bounded tool receipts leave the device only for cloud planning.\n\n03   Stay in control\nReview exact recipients and drafts. Android completes calls and sends; Nexus reports the handoff, not delivery.","۰۱   محلی شروع کنید\n«گزارش دستگاه و بعد فهرست برنامه‌ها» بدون شبکه اجرا می‌شود.\n\n۰۲   هوش ابری\nبرای فرمان آزاد یا شرطی، کلید شخصی جمینای را اضافه کنید. فرمان و رسید محدود ابزار برای برنامه‌ریزی ابری ارسال می‌شود.\n\n۰۳   کنترل در دست شماست\nگیرنده و متن را بررسی کنید. تماس و ارسال در برنامهٔ اندروید انجام می‌شود؛ نکسوس فقط واگذاری را گزارش می‌کند."));s.action(t("Run the local sequence","اجرای دنبالهٔ محلی"),true,()->{db.prefs.edit().putBoolean("intro",true).apply();s.close();a.page("agent");a.submit(t("device report then list apps","گزارش دستگاه و بعد فهرست برنامه‌ها"),false);});s.action(t("Got it","متوجه شدم"),false,()->{db.prefs.edit().putBoolean("intro",true).apply();s.close();a.changed();});s.show();}
    public void provider(){if(a.validating||a.agent.running){a.toast(t("Wait for the current operation or cancel it first.","ابتدا عملیات جاری را تمام یا لغو کنید."));return;}Kit.Sheet s=k.new Sheet(t("Gemini connection","اتصال جمینای"));s.note(cloudStatus());s.note(t("Personal key mode. Google receives free-form instructions and compact tool observations. Contact matches, screen content and notes are not uploaded as tool results. Your key is encrypted with Android Keystore. Free-tier limits depend on the account and model.","حالت کلید شخصی: فرمان‌های آزاد و رسیدهای محدود ابزار به گوگل فرستاده می‌شوند؛ نتایج مخاطبان، متن صفحه و یادداشت‌ها ارسال نمی‌شوند. کلید با Android Keystore رمز می‌شود. سهمیه به حساب و مدل بستگی دارد."));EditText key=k.input(a.vault.present()?t("Stored key • enter only to replace","کلید ذخیره شده · فقط برای تعویض وارد کنید"):t("Gemini API key","کلید API جمینای"),"",false);key.setContentDescription("api_key");key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);key.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);key.setSaveEnabled(false);k.add(s.body,key,-1,-2);k.gap(s.body,12);k.add(s.body,k.text(t("Model identifier","شناسهٔ مدل"),12,k.sub,1),-1,-2);k.gap(s.body,5);EditText model=k.input("gemini-…",a.gemini.model(),false);model.setContentDescription("model_id");k.add(s.body,model,-1,-2);k.gap(s.body,14);
        Consumer<Boolean> save=probe->{String id=model.getText().toString().trim(),secret=key.getText().toString().trim();if(!Gemini.validModel(id)){model.setError(t("Enter a valid gemini-… identifier","شناسهٔ معتبر gemini-… وارد کنید"));return;}if(secret.isEmpty()&&!a.vault.present()){key.setError(t("Enter your own API key","کلید خود را وارد کنید"));return;}try{boolean modified=!secret.isEmpty()||!id.equals(a.gemini.model());if(!secret.isEmpty())a.vault.save(secret);SharedPreferences.Editor editor=db.prefs.edit().putString("model",id);if(modified)editor.putBoolean("verified",false);editor.apply();key.setText("");s.close();a.changed();if(probe)testProvider();else a.toast(t("Configuration saved. Test to verify access.","تنظیمات ذخیره شد؛ برای بررسی، اتصال را آزمایش کنید."));}catch(Exception e){key.setError(t("Key format or secure storage unavailable.","قالب کلید یا ذخیرهٔ امن نامعتبر است."));}};
        s.action(t("Save & test function calling","ذخیره و آزمایش فراخوانی ابزار"),true,()->save.accept(true));s.action(t("Save configuration","ذخیرهٔ تنظیمات"),false,()->save.accept(false));if(a.vault.present())s.action(t("Remove stored key","حذف کلید ذخیره‌شده"),false,()->{s.close();a.approval(t("Remove Gemini key?","حذف کلید جمینای؟"),t("Cloud planning will be disabled. Local tools remain available.","برنامه‌ریزی ابری غیرفعال می‌شود. ابزارهای محلی باقی می‌مانند."),ok->{if(ok)try{a.vault.clear();db.prefs.edit().putBoolean("verified",false).apply();a.changed();}catch(Exception e){a.toast(t("Secure storage error","خطای حافظهٔ امن"));}});});s.dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);s.show();}
    private void testProvider(){a.validating=true;db.prefs.edit().putBoolean("verified",false).apply();a.changed();a.worker.execute(()->{String msg;boolean passed=false;try{a.gemini.probe();passed=true;msg=t("The selected model returned the expected function call. No device action was invoked.","مدل فراخوانی ابزار مورد انتظار را برگرداند. هیچ اقدام دستگاهی انجام نشد.");}catch(Exception ex){msg=ex instanceof Gemini.Failure?ex.getMessage():t("Provider check failed. Check network, key and model availability.","بررسی اتصال ناموفق بود؛ شبکه، کلید و مدل را بررسی کنید.");}boolean ok=passed;String result=msg;a.main.post(()->{if(a.isDestroyed())return;a.validating=false;db.prefs.edit().putBoolean("verified",ok).apply();a.changed();if(a.foreground())a.info(ok?t("Connection verified","اتصال تأیید شد"):t("Connection not verified","اتصال تأیید نشد"),result);});});}
    public void appPicker(){Kit.Sheet s=k.new Sheet(t("Application registry","فهرست برنامه‌ها"));EditText q=k.input(t("Search name or package","جست‌وجوی نام یا بسته"),"",false);k.add(s.body,q,-1,-2);k.gap(s.body,10);LinearLayout results=k.col();k.add(s.body,results,-1,-2);Runnable show=()->{results.removeAllViews();String query=Text.norm(q.getText().toString());int count=0;for(AppIndex.App app:a.apps){if(!Text.norm(app.name+" "+app.pkg).contains(query))continue;k.item(results,"smartphone",Kit.BLUE,app.name,app.pkg,()->{s.close();a.run(new Call("launch_app","name",app.pkg));});if(++count>=60)break;}if(count==0)k.add(results,k.text(a.indexed?t("No matching launchable activity.","فعالیت قابل اجرایی یافت نشد."):t("Indexing applications…","نمایه‌سازی برنامه‌ها…"),14,k.sub,0),-1,-2);};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){show.run();}public void afterTextChanged(Editable e){}});show.run();s.action(t("Refresh registry","بازخوانی فهرست"),false,()->{s.close();a.index();a.toast(t("Refreshing application registry","در حال بازخوانی فهرست"));});s.show();}
    public void access(){Kit.Sheet s=k.new Sheet(t("Optional window receipts","رسید اختیاری پنجره"));s.note(t("Android grants this service powerful accessibility access. Nexus narrows it to one expected package for at most 4.5 seconds per handoff. It can confirm a window and, only for the manually chosen Display walkthrough, find a scrollable control and scroll once. It never reads labels or passwords, captures screens, types, taps or submits forms. No accessibility data goes to Gemini. Enable or disable it yourself in Android settings.","اندروید دسترسی گستردهٔ دسترس‌پذیری می‌دهد؛ نکسوس آن را فقط برای بستهٔ مورد انتظار و حداکثر ۴٫۵ ثانیه به کار می‌گیرد. تنها در پیمایش دستی نمایشگر، یک کنترل قابل پیمایش پیدا می‌کند. هیچ متن یا رمزی نمی‌خواند، تصویر نمی‌گیرد و فرمی تکمیل یا ارسال نمی‌کند. هیچ دادهٔ دسترس‌پذیری به جمینای نمی‌رود. روشن و خاموش کردن سرویس فقط با شماست."));s.action(t("Open Android accessibility settings","باز کردن تنظیمات دسترس‌پذیری"),true,()->{s.close();a.androidPage(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));});s.action(t("Keep current setting","حفظ تنظیم فعلی"),false,s::close);s.show();}
    public void permissions(){Kit.Sheet s=k.new Sheet(t("Permission ledger","فهرست مجوزها"));for(String p:Arrays.asList(Manifest.permission.RECORD_AUDIO,Manifest.permission.READ_CONTACTS,Manifest.permission.POST_NOTIFICATIONS)){if(p.equals(Manifest.permission.POST_NOTIFICATIONS)&&Build.VERSION.SDK_INT<33)continue;boolean ok=a.checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;s.note(p.substring(p.lastIndexOf('.')+1)+"   ·   "+(ok?t("Granted","مجاز"):t("Not granted","بدون مجوز")));}s.note(t("No location, SMS sending, direct-call, broad storage or all-packages permission. Android asks for access when a tool needs it.","هیچ مجوز مکان، ارسال پیامک، تماس مستقیم، حافظهٔ کلی یا همهٔ بسته‌ها درخواست نمی‌شود. مجوزها هنگام نیاز ابزار درخواست می‌شوند."));s.action(t("Manage in Android","مدیریت در اندروید"),true,()->{s.close();a.androidPage(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.fromParts("package",a.getPackageName(),null)));});s.show();}
    private void voice(){Kit.Sheet s=k.new Sheet(t("Voice configuration","پیکربندی صدا"));s.note(t("Speech services and language packs are supplied by your device. Continuous turns stop when Nexus leaves the foreground. No wake word or background recording.","سرویس گفتار و بستهٔ زبانی را دستگاه فراهم می‌کند. مکالمه هنگام خروج از پیش‌زمینه متوقف می‌شود. ضبط پس‌زمینه یا کلمهٔ بیدارباش ندارد."));for(String key:Arrays.asList("speak","continuous")){boolean on=db.prefs.getBoolean(key,key.equals("speak"));String text=key.equals("speak")?t("Spoken voice replies","پاسخ صوتی"):t("Continuous foreground turns","مکالمهٔ پیوسته در پیش‌زمینه");s.action(text+"   ·   "+(on?t("On","روشن"):t("Off","خاموش")),false,()->{db.prefs.edit().putBoolean(key,!on).apply();s.close();voice();});}s.action(t("Speaking speed","سرعت گفتار")+"   ·   "+db.prefs.getFloat("speed",1)+"×",false,()->{s.close();select(t("Speaking speed","سرعت گفتار"),Arrays.asList("0.8","1.0","1.15","1.3"),x->db.prefs.edit().putFloat("speed",Float.parseFloat(x)).apply());});s.action(t("Installed voice","صدای نصب‌شده")+"   ·   "+a.tag(),false,()->{s.close();List<String> voices=new ArrayList<>(a.voice.voices(a.tag()));voices.add(0,t("Engine default","پیش‌فرض موتور"));select(t("Installed voices","صداهای نصب‌شده"),voices,x->db.prefs.edit().putString("voice_"+a.tag(),x.equals(voices.get(0))?"":x).apply());});s.show();}
    public String kind(String key){switch(key){case "note":return t("Note","یادداشت");case "shortcut":return t("Shortcut","میان‌بر");case "app_alias":return t("App alias","نام مستعار برنامه");case "contact_alias":return t("Contact alias","نام مستعار مخاطب");default:return t("All","همه");}}
    public void entry(Map<String,String> old){if(!db.memoryOn()){a.toast(t("Enable memory in Privacy controls first.","ابتدا حافظه را در کنترل حریم خصوصی فعال کنید."));return;}Kit.Sheet s=k.new Sheet(old==null?t("New memory entry","ورودی جدید حافظه"):t("Edit memory entry","ویرایش حافظه"));s.note(t("Store only non-secret information. Shortcuts run through the same permission and approval checks as typed commands.","فقط اطلاعات غیرمحرمانه ذخیره کنید. اجرای میان‌بر همان مجوزها و تأییدهای فرمان متنی را لازم دارد."));String[] picked={old==null?"note":old.get("kind")};List<String> kinds=Arrays.asList("note","shortcut","app_alias","contact_alias");TextView type=k.button(kind(picked[0])+"   ▾",false,()->{});k.tap(type,()->{List<String> opts=new ArrayList<>();for(String kv:kinds)opts.add(kind(kv));a.pick(t("Entry type","نوع ورودی"),opts,i->{if(i>=0){picked[0]=kinds.get(i);type.setText(kind(picked[0])+"   ▾");}});},t("Entry type","نوع ورودی"));k.add(s.body,type,-1,-2);k.gap(s.body,8);EditText name=k.input(t("Title or trigger phrase","عنوان یا عبارت آغازگر"),old==null?"":old.get("name"),false),val=k.input(t("Note, command, or matching name","یادداشت، فرمان یا نام مقصد"),old==null?"":old.get("value"),true);name.setContentDescription("memory_name");val.setContentDescription("memory_value");k.add(s.body,name,-1,-2);k.gap(s.body,8);k.add(s.body,val,-1,-2);k.gap(s.body,12);s.action(t("Save entry","ذخیرهٔ ورودی"),true,()->{try{db.save(old==null?-1:Long.parseLong(old.get("id")),picked[0],name.getText().toString(),val.getText().toString());s.close();a.changed();}catch(Exception e){a.toast(t("Use a unique title and non-secret value within the limits.","عنوان یکتا و مقدار غیرمحرمانه وارد کنید."));}});if(old!=null){if(old.get("kind").equals("shortcut"))s.action(t("Run saved shortcut","اجرای میان‌بر ذخیره‌شده"),false,()->{s.close();a.page("agent");a.submit(old.get("name"),false);});s.action(t("Delete entry","حذف ورودی"),false,()->{s.close();a.approval(t("Delete entry?","حذف ورودی؟"),old.get("name"),ok->{if(ok){db.forget(Long.parseLong(old.get("id")));a.changed();}});});}s.show();}
    public void privacy(){if(a.agent.running){a.toast(t("Finish or cancel the active task first.","ابتدا وظیفهٔ جاری را پایان دهید یا لغو کنید."));return;}Kit.Sheet s=k.new Sheet(t("Privacy controls","کنترل حریم خصوصی"));s.note(t("Explicit notes and shortcuts stay in private SQLite storage. History retains tool names, times and result codes, not message bodies, numbers or raw commands. Pausing does not delete existing rows. Usage counts and scheduled reminders are separate.","یادداشت و میان‌بر در SQLite خصوصی می‌مانند. تاریخچه فقط نام ابزار، زمان و کد نتیجه را نگه می‌دارد، نه متن پیام، شماره یا فرمان خام. توقف به معنای حذف نیست. شمارنده‌های مصرف و یادآورها جدا هستند."));for(String key:Arrays.asList("memory","history")){boolean enabled=db.prefs.getBoolean(key,true);s.action((key.equals("memory")?t("Memory retrieval & writes","بازیابی و ثبت حافظه"):t("Audit history","تاریخچهٔ فعالیت"))+"   ·   "+(enabled?t("On","روشن"):t("Off","خاموش")),false,()->{db.prefs.edit().putBoolean(key,!enabled).apply();a.agent.clearSession();s.close();privacy();});}s.action(t("Erase entries & task history","حذف حافظه و تاریخچه"),false,()->{s.close();a.approval(t("Erase local memory?","حذف حافظهٔ محلی؟"),t("Permanently delete every saved entry, shortcut and task receipt. This cannot be undone. API configuration and scheduled reminders are not affected.","همهٔ ورودی‌ها، میان‌برها و رسیدها برای همیشه حذف می‌شوند. کلید جمینای و یادآورها تغییر نمی‌کنند."),ok->{if(ok){db.clearHistory();db.clearMemory();a.agent.clearSession();a.changed();}});});s.show();}
